def countSubstrings(s, t):
    res = 0
    n, m = len(s), len(t)
    for i in range(n):
        for j in range(m):
            mismatch = 0
            k = 0
            while i + k < n and j + k < m:
                if s[i + k] != t[j + k]:
                    mismatch += 1
                if mismatch > 1:
                    break
                if mismatch == 1:
                    res += 1
                k += 1
    return res
